```yaml
name: Notify dev channel

on:
  push:
    branches: [master]
    paths:
      - src/**

jobs:
  notify:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Notify dev channel
        uses: actions/github-script@v6
        with:
          script: |
            const commitMessage = github.event.head_commit && github.event.head_commit.message
              ? github.event.head_commit.message
              : '';
            const mergeRegex = /Merge pull request #([0-9]+)/i;
            const match = commitMessage.match(mergeRegex);
            if (!match) {
              core.info('No merge commit detected, skipping.');
              return;
            }
            const prNumber = match[1];
            core.info(`Detected merged PR #${prNumber}`);

            // Get PR details
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            const prComment = `## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\``;

            // Post comment on PR
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: prComment
            });

            // Find linked issues in PR body
            const issueRegex = /(Closes|Fixes|Resolves)\s+#([0-9]+)/gi;
            const issues = [];
            let m;
            while ((m = issueRegex.exec(pr.body)) !== null) {
              issues.push(m[2]);
            }

            if (issues.length === 0) {
              core.info('No linked issues found.');
              return;
            }

            const issueComment = `## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${prNumber}) and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\``;

            for (const issueNumber of issues) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                body: issueComment
              });
              core.info(`Commented on issue #${issueNumber}`);
            }
```

